app CanLeave uses=[leave]

package leave label="Leave"@{nl="Verlof"}
 use employee {Employee,can_work,test_worker}
 use rent_catalog {Location,test_site}
 use shift {ScheduleV1 as StaffSchedule} from=deployment.staff_schedule
 Given
  message label_preferences_year = "Year"@{nl="Jaar"}
  message label_preferences_bucket = "Leave category"@{nl="Verlofcategorie"}
  message label_Allowance_days = "Days"@{nl="Dagen"}
  message label_Request_from = "Start"@{nl="Begin"}
  message label_Request_until = "End"@{nl="Einde"}
  message label_Request_reviewer = "Reviewer"@{nl="Beoordelaar"}
  message label_Request_state_pending = "Pending"@{nl="In afwachting"}
  preferences { year:int? label=label_preferences_year, bucket:text? label=label_preferences_bucket }
  role hr label="HR staff"@{nl="HR-medewerker"}
  role leave_reviewer label="Leave reviewer"@{nl="Verlofbeoordelaar"}
  Calendar in Employee { name:text, timezone:timezone, revision:int=1 } label="Working calendar"@{nl="Werkkalender"}
  Day in Calendar { date:date unique label="Date"@{nl="Datum"}, working:bool label="Working day"@{nl="Werkdag"} } label="Calendar day"@{nl="Kalenderdag"}
  Allowance in Employee { year:int label=label_preferences_year, bucket:text label=label_preferences_bucket, days:int=20 min=0 label=label_Allowance_days } label="Allowance"@{nl="Tegoed"}
  Request in Calendar { from:date label=label_Request_from, until:date label=label_Request_until, bucket:text label=label_preferences_bucket, reason:text, reviewer:user label=label_Request_reviewer, calendar_version:int label="Calendar version"@{nl="Kalenderversie"}, state:enum(pending,approved,rejected,withdrawn,cancelled)=pending label={text="State"@{nl="Status"},values={pending=label_Request_state_pending,approved="Approved"@{nl="Goedgekeurd"},rejected="Rejected"@{nl="Afgewezen"},withdrawn="Withdrawn"@{nl="Ingetrokken"},cancelled="Cancelled"@{nl="Geannuleerd"}}}, decision:text? label="Decision"@{nl="Besluit"}, schedule_source:text? label="Schedule source"@{nl="Planningsbron"}, sync:enum(none,pending,confirmed,conflict,unavailable)=none label={text="Schedule synchronization"@{nl="Planningsafstemming"},values={pending=label_Request_state_pending,none="None"@{nl="Geen"},confirmed="Confirmed"@{nl="Bevestigd"},conflict="Conflict"@{nl="Conflict"},unavailable="Unavailable"@{nl="Niet beschikbaar"}}} } label="Leave request"@{nl="Verlofaanvraag"}
  Portion in Request { allowance:Allowance, days:int label=label_Allowance_days, dates:date[]! label="Working dates"@{nl="Werkdagen"} } label="Yearly leave portion"@{nl="Verlofdeel per jaar"}
  derive Day.year:int = date_year(row.date) label=label_preferences_year
  derive Allowance.remaining:int = row.days-sum(Portion as portion where portion.allowance==row and portion.parent.state==approved select portion.days) label="Remaining"@{nl="Resterend"}
  policy Calendar read=authenticated where=row.parent.user==actor
  policy Calendar read=hr
  policy Day read=authenticated where=row.parent.parent.user==actor
  policy Day read=hr
  policy Allowance read=authenticated where=row.parent.user==actor
  policy Allowance read=hr
  policy Request read=authenticated where=row.parent.parent.user==actor
  policy Request read=leave_reviewer where=row.reviewer==actor and can_work(actor,row.parent.parent.home)
  policy Request read=hr
  policy Request read=members where=can_work(actor,row.parent.parent.home) fields=from,until,state
  policy Portion read=authenticated where=row.parent.parent.parent.user==actor
  policy Portion read=hr or leave_reviewer
  unique Allowance fields=year,bucket
  require Request: row.from<=row.until and row.reviewer!=row.parent.parent.user
  require Allowance: row.remaining>=0
  lock Request fields=from,until,bucket,reason,reviewer,calendar_version
  lock Portion fields=allowance,days,dates
  fixture calendar=Calendar {parent=test_worker,name="Working days",timezone="Europe/Brussels"}
  fixture pending=Request {parent=calendar,from=date("2099-01-02"),until=date("2099-01-02"),bucket="vacation",reason="Holiday",reviewer=other,calendar_version=1}
  fixture reviewer_worker=Employee {user=other,home=test_site,locations=[test_site],start=date("2026-10-01"),role="reviewer"}
  fixture december_30=Day {parent=calendar,date=date("2099-12-30"),working=true}
  fixture december_31=Day {parent=calendar,date=date("2099-12-31"),working=true}
  fixture january_1=Day {parent=calendar,date=date("2100-01-01"),working=false}
  fixture january_2=Day {parent=calendar,date=date("2100-01-02"),working=true}
  fixture allowance_2099=Allowance {parent=test_worker,year=2099,bucket="vacation"}
  fixture allowance_2100=Allowance {parent=test_worker,year=2100,bucket="vacation"}
 When
  crud Calendar by=hr fields=name,timezone,revision delete=none
  crud Day by=hr fields=date,working delete=none
  crud Allowance by=hr fields=days create_fields=year,bucket,days delete=none
  scenario request(calendar:Calendar,from:date label=label_Request_from,until:date label=label_Request_until,bucket:text label=label_preferences_bucket,reason:text,reviewer:user label=label_Request_reviewer) by=members label="Request leave"@{nl="Verlof aanvragen"}
   require calendar.parent.user==actor and calendar.parent.active and from<=until and reviewer!=actor and can_work(reviewer,calendar.parent.home) and trim(reason)!=""
   require not any(calendar.Request as old,old.state in [pending,approved] and overlaps(from,add_days(until,1),old.from,add_days(old.until,1)))
   require all(dates(from,add_days(until,1),3660) as day_date,any(calendar.Day as day,day.date==day_date))
   do
    let selected=calendar.Day as day where from<=day.date and day.date<=until and day.working
    require count(selected)>0
    create Request {parent=calendar,from,until,bucket,reason,reviewer,calendar_version=calendar.revision} as request
    for year in group(selected as day,day.year) limit=10
     let allowance=first(calendar.parent.Allowance as allowance where allowance.year==year.key and allowance.bucket==bucket order=allowance.id)
     require allowance!=null
     create Portion {parent=request,allowance,days=count(year.items),dates=year.items as day select day.date} as portion
   examples seed=[reviewer_worker,december_30,december_31,january_1,january_2,allowance_2099,allowance_2100] calendar=calendar from=date("2099-12-30") until=date("2100-01-02") bucket="vacation" reason="Year-end leave" reviewer=other
    as -> Portion as portion where portion.parent.parent==calendar order=portion.allowance.year select portion.allowance.year,Portion as portion where portion.parent.parent==calendar order=portion.allowance.year select portion.days
    members -> [2099,2100],[2,1]
   examples seed=[reviewer_worker,december_30,december_31,january_2,allowance_2099,allowance_2100] calendar=calendar from=date("2099-12-30") until=date("2100-01-02") bucket="vacation" reason="Year-end leave" reviewer=other
    as -> count(calendar.Request)
    members -> error(rule_failed)
  scenario decide(request:Request,approve:bool label="Approve"@{nl="Goedkeuren"},reason:text) by=leave_reviewer label="Record decision"@{nl="Besluit vastleggen"}
   require request.state==pending and request.reviewer==actor and request.parent.parent.user!=actor and can_work(actor,request.parent.parent.home) and trim(reason)!=""
   do
    if approve
     require all(request.Portion as portion,portion.days<=portion.allowance.remaining)
     set request {state=approved,decision=reason,schedule_source=operation.id,sync=pending}
     send StaffSchedule.reserve {value={source=operation.id,employee=request.parent.parent.user,location=request.parent.parent.home.id,from=local_instant(request.from,"00:00",request.parent.timezone,fold=earlier),until=local_instant(add_days(request.until,1),"00:00",request.parent.timezone,fold=earlier),skill="absence",kind=absence,revision=request.version+1}} as delivery
    else
     set request {state=rejected,decision=reason}
  scenario withdraw(request:Request) by=members label="Withdraw"@{nl="Intrekken"}
   require request.parent.parent.user==actor and request.state==pending
   do set request {state=withdrawn}
   examples request=pending
    as,request.state -> request.state
    members,pending -> withdrawn
    members,approved -> error(rule_failed)
    public,pending -> error(forbidden)
  scenario cancel(request:Request,reason:text) by=hr or leave_reviewer
   require request.state==approved and trim(reason)!="" and (hr or request.reviewer==actor)
   do
    set request {state=cancelled,decision=reason}
    if request.schedule_source!=null
     send StaffSchedule.release {source=request.schedule_source,revision=request.version} as delivery
  scenario schedule_result on=StaffSchedule.changed
   do
    for request in Request as item where item.schedule_source==event.value.source limit=1
     if event.value.state==confirmed
      set request {sync=confirmed}
     else
      if event.value.state==unavailable
       set request {sync=conflict}
      else
       set request {sync=unavailable}
 Then
  page /leave/mine title="My leave"@{nl="Mijn verlof"}
   require members
   card "Leave dates and allowance"@{nl="Verlofdatums en tegoed"} layout=columns
    card "Working calendar and request intake"@{nl="Werkkalender en verlofaanvraag"}
     list Calendar display=split
      form request
      table row.Day columns=date,working
      table row.Request columns=from,until,bucket,state,decision,sync order=-from filter=bucket,state defaults={bucket=preferences.bucket}
       action withdraw
    card "Annual allowance"@{nl="Jaarlijks verloftegoed"}
     table Allowance columns=year,bucket,days,remaining filter=year,bucket defaults={year=preferences.year,bucket=preferences.bucket}

  page /leave/review title="Leave review"@{nl="Verlof beoordelen"}
   require hr or leave_reviewer
   card "Assigned review"@{nl="Toegewezen beoordeling"}
    table Request columns=from,until,reason,state,decision,sync order=from filter=bucket,state defaults={bucket=preferences.bucket} display=split
     actions decide,cancel
     details "Recorded date portions"@{nl="Vastgelegde datumdelen"}
      list row.Portion
       text row.allowance,row.days,row.dates
     history

  page /leave/absence title="Absence dates"@{nl="Afwezigheidsdatums"}
   require members
   card "Scoped absence dates"@{nl="Afwezigheid binnen scope"}
    table Request columns=from,until,state filter=state
app CanShift uses=[shift]

app StaffScheduling uses=[CanLeave,CanShift]

package shift label="Staff scheduling"@{nl="Personeelsplanning"}
 use employee {Employee,can_work,test_worker}
 use rent_catalog {Location,test_site}
 use shift {ScheduleIngressV1 as ScheduleRequests} from=deployment.schedule_ingress
 use std {OperationOutcome}
 Given
  preferences { location:Location? }
  message title_roster = "Staff roster"@{nl="Personeelsrooster"}
  message label_CommitmentRequest_source = "Source reference"@{nl="Bronreferentie"}
  message label_CommitmentRequest_employee = "Employee"@{nl="Medewerker"}
  message label_CommitmentRequest_from = "From"@{nl="Van"}
  message label_CommitmentRequest_until = "Until"@{nl="Tot"}
  message label_CommitmentRequest_before = "Travel buffer before"@{nl="Reisbuffer vooraf"}
  message label_CommitmentRequest_after = "Travel buffer after"@{nl="Reisbuffer achteraf"}
  message label_CommitmentRequest_skill = "Required skill"@{nl="Vereiste vaardigheid"}
  message label_CommitmentRequest_kind = "Kind"@{nl="Soort"}
  message label_CommitmentRequest_kind_duty = "Staff duty"@{nl="Personeelsdienst"}
  message label_CommitmentRequest_kind_visit = "Service visit"@{nl="Servicebezoek"}
  message label_CommitmentRequest_kind_appointment = "Host appointment"@{nl="Hostafspraak"}
  message label_CommitmentRequest_kind_absence = "Absence"@{nl="Afwezigheid"}
  message label_CommitmentRequest_kind_interview = "Interview"@{nl="Sollicitatiegesprek"}
  message label_Duty_role = "Work role"@{nl="Werkrol"}
  message label_Duty_override_reason = "Coverage override reason"@{nl="Reden voor bezettingsafwijking"}
  message label_Swap_substitute = "Proposed substitute"@{nl="Voorgestelde vervanger"}
  export contract CommitmentRequest { source:text label=label_CommitmentRequest_source, employee:user label=label_CommitmentRequest_employee, location:text, from:datetime label=label_CommitmentRequest_from, until:datetime label=label_CommitmentRequest_until, before:duration=0m label=label_CommitmentRequest_before, after:duration=0m label=label_CommitmentRequest_after, skill:text label=label_CommitmentRequest_skill, kind:enum(duty,visit,appointment,absence,interview) label={text=label_CommitmentRequest_kind,values={duty=label_CommitmentRequest_kind_duty,visit=label_CommitmentRequest_kind_visit,appointment=label_CommitmentRequest_kind_appointment,absence=label_CommitmentRequest_kind_absence,interview=label_CommitmentRequest_kind_interview}}, revision:int } label="Employee commitment request"@{nl="Aanvraag personeelsinzet"}
  export capability ScheduleV1 version=1
   reserve(value:CommitmentRequest) -> OperationOutcome
   stage(value:CommitmentRequest,previous_source:text,previous_revision:int) -> OperationOutcome
   release(source:text,revision:int) -> OperationOutcome
   event changed { value:OperationOutcome }
  role scheduler label="Scheduler"@{nl="Roosterplanner"}
  Roster { name:text unique } label=title_roster
  Availability in Roster { employee:Employee label=label_CommitmentRequest_employee, from:datetime label=label_CommitmentRequest_from, until:datetime label=label_CommitmentRequest_until, available:bool=true label="Available for work"@{nl="Beschikbaar voor werk"} } label="Employee availability"@{nl="Medewerkersbeschikbaarheid"}
  Commitment in Roster { employee:Employee label=label_CommitmentRequest_employee, location:Location, from:datetime label=label_CommitmentRequest_from, until:datetime label=label_CommitmentRequest_until, before:duration=0m label=label_CommitmentRequest_before, after:duration=0m label=label_CommitmentRequest_after, skill:text label=label_CommitmentRequest_skill, kind:enum(duty,visit,appointment,absence,interview) label={text=label_CommitmentRequest_kind,values={duty=label_CommitmentRequest_kind_duty,visit=label_CommitmentRequest_kind_visit,appointment=label_CommitmentRequest_kind_appointment,absence=label_CommitmentRequest_kind_absence,interview=label_CommitmentRequest_kind_interview}}, source:text unique label=label_CommitmentRequest_source, previous:Commitment? label="Retained predecessor"@{nl="Behouden voorganger"}, revision:int=1, active:bool=true, conflict:bool=false label="Commitment conflict"@{nl="Inzetconflict"} } label="Employee commitment"@{nl="Personeelsinzet"}
  Release in Roster { source:text unique label=label_CommitmentRequest_source, revision:int min=1 } label="Released source fence"@{nl="Vrijgavegrens bron"}
  lock Release fields=source
  Duty in Commitment { role:text label=label_Duty_role, published:bool=false label="Published"@{nl="Gepubliceerd"}, override_reason:text? label=label_Duty_override_reason } label="Published duty"@{nl="Gepubliceerde dienst"}
  Coverage in Roster { location:Location, role:text label=label_Duty_role, from:datetime label=label_CommitmentRequest_from, until:datetime label=label_CommitmentRequest_until, minimum:int=1 min=1 label="Minimum staff"@{nl="Minimumbezetting"} } label="Coverage requirement"@{nl="Bezettingsvereiste"}
  Swap in Duty { substitute:Employee label=label_Swap_substitute, original:Employee label="Original employee"@{nl="Oorspronkelijke medewerker"}, revision:int, state:enum(open,accepted,rejected,obsolete)=open label={text="State"@{nl="Status"},values={open="Open"@{nl="Open"},accepted="Accepted"@{nl="Geaccepteerd"},rejected="Rejected"@{nl="Afgewezen"},obsolete="Superseded"@{nl="Achterhaald"}}} } label="Shift swap"@{nl="Dienstruil"}
  export capability ScheduleIngressV1 version=1
   event reserve { roster:Roster, employee:Employee, location:Location, value:CommitmentRequest }
   event stage { roster:Roster, employee:Employee, location:Location, value:CommitmentRequest, previous_source:text, previous_revision:int }
   event release { roster:Roster, source:text, revision:int }
  export event ReservationOutcome { value:OperationOutcome }
  policy Roster read=scheduler
  policy Availability read=scheduler
  policy Availability read=members where=row.employee.user==actor
  policy Commitment read=scheduler and can_work(actor,row.location)
  policy Commitment read=members where=row.employee.user==actor and (row.kind!=duty or any(row.Duty as duty,duty.published))
  policy Duty read=scheduler and can_work(actor,row.parent.location)
  policy Duty read=members where=row.published and row.parent.employee.user==actor
  policy Coverage read=scheduler and can_work(actor,row.location)
  policy Swap read=scheduler
  policy Swap read=members where=row.substitute.user==actor or row.original.user==actor
  require Availability: row.from<row.until
  require Commitment: row.from<row.until and row.before>=0m and row.after>=0m
  derive fits(roster:Roster,employee:Employee,from:datetime,until:datetime,before:duration,after:duration,skip:Commitment?):bool = employee.active and any(roster.Availability as window,window.employee==employee and window.available and window.from<=from-before and until+after<=window.until) and not any(roster.Availability as window,window.employee==employee and not window.available and overlaps(from-before,until+after,window.from,window.until)) and not any(roster.Commitment as existing,existing!=skip and existing.employee==employee and existing.active and overlaps(from-before,until+after,existing.from-existing.before,existing.until+existing.after))
  lock Swap fields=substitute,original,revision
  fixture roster=Roster {name="Operator"}
  fixture substitute=Employee {user=other,home=test_site,start=date("2026-10-01"),role="Reception",skills=["reception"]}
  fixture assignment=Commitment {parent=roster,employee=test_worker,location=test_site,from=datetime("2099-01-01T09:00:00Z"),until=datetime("2099-01-01T17:00:00Z"),skill="reception",kind=duty,source="duty"}
  fixture duty=Duty {parent=assignment,role="Reception",published=true}
  fixture proposed=Swap {parent=duty,substitute=test_worker,original=substitute,revision=1}
 When
  crud Availability by=members fields=from,until,available create_fields=employee,from,until,available when=row.employee.user==actor and row.employee.active delete=none
  crud Coverage by=scheduler fields=role,from,until,minimum create_fields=location,role,from,until,minimum when=can_work(actor,row.location) delete=none
  scenario assign(roster:Roster,employee:Employee,location:Location,from:datetime label=label_CommitmentRequest_from,until:datetime label=label_CommitmentRequest_until,role:text label=label_Duty_role,skill:text label=label_CommitmentRequest_skill,before:duration=0m label=label_CommitmentRequest_before,after:duration=0m label=label_CommitmentRequest_after) by=scheduler
   require can_work(actor,location) and can_work(employee.user,location) and skill in employee.skills and fits(roster,employee,from,until,before,after,null)
   do
    create Commitment {parent=roster,employee,location,from,until,before,after,skill,kind=duty,source=operation.id} as commitment
    create Duty {parent=commitment,role} as duty
  scenario publish(duty:Duty,override_reason:text? label=label_Duty_override_reason) by=scheduler
   require can_work(actor,duty.parent.location) and duty.parent.active and not duty.published
   do
    require override_reason!=null or all(duty.parent.parent.Coverage as window,window.location!=duty.parent.location or window.role!=duty.role or count(Duty as other where other.parent.active and other.role==window.role and other.parent.location==window.location and other.parent.from<=window.from and window.until<=other.parent.until)>=window.minimum)
    set duty {published=true,override_reason}
  scenario request_swap(duty:Duty,substitute:Employee label=label_Swap_substitute) by=members label="Request shift swap"@{nl="Dienstruil aanvragen"}
   require duty.published and duty.parent.active and duty.parent.employee.user==actor and substitute.user!=actor and substitute.active and duty.parent.skill in substitute.skills
   do create Swap {parent=duty,substitute,original=duty.parent.employee,revision=duty.parent.version} as swap
  scenario accept(swap:Swap) by=members label="Accept shift swap"@{nl="Dienstruil accepteren"}
   require swap.state==open and swap.substitute.user==actor and swap.substitute.active and swap.parent.parent.employee==swap.original and swap.parent.parent.version==swap.revision and swap.parent.parent.skill in swap.substitute.skills
   require fits(swap.parent.parent.parent,swap.substitute,swap.parent.parent.from,swap.parent.parent.until,swap.parent.parent.before,swap.parent.parent.after,swap.parent.parent)
   require not any(swap.parent.parent.parent.Commitment as dependent,dependent.active and dependent.employee==swap.original and dependent.kind in [visit,appointment] and overlaps(dependent.from,dependent.until,swap.parent.parent.from,swap.parent.parent.until))
   do
    set swap.parent.parent {employee=swap.substitute,revision=swap.parent.parent.revision+1}
    set swap {state=accepted}
    for other in swap.parent.Swap as item where item!=swap and item.state==open limit=100
     set other {state=obsolete}
  scenario decline(swap:Swap) by=members label="Decline shift swap"@{nl="Dienstruil afwijzen"}
   require swap.substitute.user==actor and swap.state==open
   do set swap {state=rejected}
   examples swap=proposed
    as,swap.state -> swap.state,assignment.employee
    members,open -> rejected,test_worker
    members,accepted -> error(rule_failed)
    public,open -> error(forbidden)
  scenario cancel(duty:Duty,reason:text) by=scheduler
   require can_work(actor,duty.parent.location) and duty.parent.active and trim(reason)!=""
   require not any(duty.parent.parent.Commitment as dependent,dependent.active and dependent.employee==duty.parent.employee and dependent.kind in [visit,appointment] and overlaps(dependent.from,dependent.until,duty.parent.from,duty.parent.until))
   do set duty.parent {active=false,revision=duty.parent.revision+1}
  scenario reserve_connected on=ScheduleRequests.reserve
   require event.employee.user==event.value.employee and event.location.id==event.value.location and event.employee.active and event.value.from<event.value.until
   require can_work(event.employee.user,event.location) and (event.value.kind==absence or event.value.skill in event.employee.skills)
   do
    require not any(event.roster.Release as released,released.source==event.value.source and released.revision>=event.value.revision)
    let previous=first(event.roster.Commitment as item where item.source==event.value.source order=item.id)
    if previous!=null and previous.revision>=event.value.revision
     require previous.revision==event.value.revision and previous.employee==event.employee and previous.from==event.value.from and previous.until==event.value.until
     emit ReservationOutcome {value={source=previous.source,revision=previous.revision,state=confirmed,reference=previous.id}}
    else
     let conflicts=event.roster.Commitment as item where item!=previous and item.active and item.employee==event.employee and overlaps(event.value.from-event.value.before,event.value.until+event.value.after,item.from-item.before,item.until+item.after)
     let available=any(event.roster.Availability as window,window.employee==event.employee and window.available and window.from<=event.value.from-event.value.before and event.value.until+event.value.after<=window.until) and not any(event.roster.Availability as window,window.employee==event.employee and not window.available and overlaps(event.value.from,event.value.until,window.from,window.until))
     let compatible=all(conflicts as item,item.kind==duty and item.location==event.location and item.from<=event.value.from and event.value.until<=item.until and event.value.kind in [visit,appointment,interview])
     if event.value.kind!=absence and (not available or not compatible)
      emit ReservationOutcome {value={source=event.value.source,revision=event.value.revision,state=unavailable,detail="Employee commitment unavailable"}}
     else
      if previous==null
       create Commitment {parent=event.roster,employee=event.employee,location=event.location,from=event.value.from,until=event.value.until,before=event.value.before,after=event.value.after,skill=event.value.skill,kind=event.value.kind,source=event.value.source,revision=event.value.revision} as commitment
       emit ReservationOutcome {value={source=commitment.source,revision=commitment.revision,state=confirmed,reference=commitment.id}}
      else
       set previous {employee=event.employee,location=event.location,from=event.value.from,until=event.value.until,before=event.value.before,after=event.value.after,skill=event.value.skill,kind=event.value.kind,revision=event.value.revision,active=true}
       emit ReservationOutcome {value={source=previous.source,revision=event.value.revision,state=confirmed,reference=previous.id}}
      if event.value.kind==absence
       for conflict in conflicts limit=100
        set conflict {conflict=true}
  scenario stage_connected on=ScheduleRequests.stage
   require event.employee.user==event.value.employee and event.location.id==event.value.location and event.employee.active and event.value.from<event.value.until and event.value.before>=0m and event.value.after>=0m and event.value.revision==1 and event.value.source!=event.previous_source
   require can_work(event.employee.user,event.location) and event.value.skill in event.employee.skills
   do
    let previous=first(event.roster.Commitment as item where item.source==event.previous_source order=item.id)
    require previous!=null and previous.location==event.location and previous.kind==event.value.kind and previous.revision==event.previous_revision
    let release_fence=first(event.roster.Release as item where item.source==event.value.source order=item.id)
    let candidate=first(event.roster.Commitment as item where item.source==event.value.source order=item.id)
    if release_fence!=null
     emit ReservationOutcome {value={source=event.value.source,revision=release_fence.revision,state=released,reference=event.value.source}}
    else
     if candidate!=null
